mapper.select:
select oa_enterprise_employee.enterprise_id, oa_enterprise.enterprise_name, employee.*, employee.actual_name as employeeName from oa_enterprise_employee left join oa_enterprise on oa_enterprise_employee.enterprise_id = oa_enterprise.enterprise_id left join employee on oa_enterprise_employee.employee_id = employee.employee_id where oa_enterprise_employee.enterprise_id = #{queryForm.enterpriseId}
AND ( INSTR(employee.actual_name,#{queryForm.keyword}) OR INSTR(employee.phone,#{queryForm.keyword}) OR INSTR(employee.login_name,#{queryForm.keyword}) )
AND employee.deleted_flag = #{queryForm.deletedFlag}
